import ast

def score(program: str) -> float:
    try:
        tree = ast.parse(program)
    except Exception:
        return 0.0
    nodes = list(ast.walk(tree))
    kinds = {type(x).__name__ for x in nodes}
    a = min(len(kinds) / 40, 1)
    b = 1 - 1 / (1 + len(nodes) / 50)
    return 0.8 * a + 0.2 * b

def clip(x: float) -> float:
    return min(1.0, max(0.0, x))


