    return clip(0.8 * length(program) + 0.2 * variety(program))

def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
        nodes = sum(1 for _ in ast.walk(tree))
        if nodes < 40:
            return nodes / 100.0
        elif nodes <= 100:
            return 0.4 + (nodes - 40) / 100.0
        else:
            return 0.0
    except:
        return 0.0

