import ast

def score(program: str) -> float:
    try:
        t = ast.parse(program)
    except Exception:
        return 0.0
    k = [type(x).__name__ for x in ast.walk(t)]
    v = len(set(k)) / 40
    n = min(len(k), 400) / 400
    return min(1.0, 0.6 * v + 0.4 * n)
